import{_ as e,o as t,c as i,ae as s}from"./chunks/framework.VfpTXP3k.js";const k=JSON.parse('{"title":"常见问题","description":"身份证号码验证常见问题 — X 结尾含义、15 位转 18 位规则、校验算法原理、隐私安全说明","frontmatter":{"title":"常见问题","description":"身份证号码验证常见问题 — X 结尾含义、15 位转 18 位规则、校验算法原理、隐私安全说明"},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1785199646000}'),o={name:"guide/faq.md"};function d(r,a,l,n,h,p){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="常见问题-faq" tabindex="-1">常见问题 (FAQ) <a class="header-anchor" href="#常见问题-faq" aria-label="Permalink to &quot;常见问题 (FAQ)&quot;">​</a></h1><h2 id="身份证号码最后一位是-x-是什么意思" tabindex="-1">身份证号码最后一位是 X 是什么意思？ <a class="header-anchor" href="#身份证号码最后一位是-x-是什么意思" aria-label="Permalink to &quot;身份证号码最后一位是 X 是什么意思？&quot;">​</a></h2><p>X 是校验码的一种取值。校验码由前 17 位通过 ISO 7064:1983 MOD 11-2 加权算法计算得出，结果为 0~10 共 11 种可能。当结果为 10 时，为保证号码总长 18 位，用罗马数字 <strong>X</strong> 表示。</p><p>本库在比对校验码时统一按大写处理，输入小写 <code>x</code> 同样判定有效：</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isValid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;37012519790112881x&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// → true（小写 x 也可通过）</span></span></code></pre></div><h2 id="_15-位和-18-位身份证有什么区别" tabindex="-1">15 位和 18 位身份证有什么区别？ <a class="header-anchor" href="#_15-位和-18-位身份证有什么区别" aria-label="Permalink to &quot;15 位和 18 位身份证有什么区别？&quot;">​</a></h2><p>15 位是 1999 年之前的旧版号码，18 位是 GB 11643-1999 规定的现行版本，差异有两点：</p><ol><li><strong>出生年份</strong>：15 位用 2 位年份（<code>YYMMDD</code>，默认 19 世纪），18 位用 4 位完整年份（<code>YYYYMMDD</code>）</li><li><strong>校验码</strong>：15 位没有校验码，18 位末位是加权校验码</li></ol><p><code>toEighteen()</code> 按标准规则升级：年份补 <code>19</code>、追加计算的校验码：</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toEighteen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;110101900101001&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// → &#39;110101199001011001&#39;</span></span></code></pre></div><h2 id="验证通过就代表这个身份证号码真实存在吗" tabindex="-1">验证通过就代表这个身份证号码真实存在吗？ <a class="header-anchor" href="#验证通过就代表这个身份证号码真实存在吗" aria-label="Permalink to &quot;验证通过就代表这个身份证号码真实存在吗？&quot;">​</a></h2><p><strong>不代表。</strong> 本库执行的是<strong>离线格式校验</strong>，包括：</p><ul><li>长度与字符规则（<code>checkBaseFormat</code>）</li><li>省份行政区划代码有效性（<code>checkProvince</code>）</li><li>出生日期合法性（含闰年、大小月）</li><li>校验码一致性（MOD 11-2）</li></ul><p>一个&quot;通过验证&quot;的号码只说明它<strong>符合编码规则</strong>，无法确认该号码是否真实签发、是否对应某个真实的人。实名核验需要对接公安部一所等官方渠道，任何纯前端库都做不到。</p><h2 id="支持港澳台地区的号码吗" tabindex="-1">支持港澳台地区的号码吗？ <a class="header-anchor" href="#支持港澳台地区的号码吗" aria-label="Permalink to &quot;支持港澳台地区的号码吗？&quot;">​</a></h2><p>支持。地址码前两位按 GB/T 2260 扩展代码校验：</p><table tabindex="0"><thead><tr><th>代码</th><th>地区</th></tr></thead><tbody><tr><td><code>71</code></td><td>台湾省</td></tr><tr><td><code>81</code></td><td>香港特别行政区</td></tr><tr><td><code>82</code></td><td>澳门特别行政区</td></tr></tbody></table><h2 id="出生日期的校验规则是什么" tabindex="-1">出生日期的校验规则是什么？ <a class="header-anchor" href="#出生日期的校验规则是什么" aria-label="Permalink to &quot;出生日期的校验规则是什么？&quot;">​</a></h2><p>按公历严格校验，包括：</p><ul><li>月份必须在 1~12 之间</li><li>日期不超过当月实际天数（4/6/9/11 月 30 天，其余 31 天）</li><li><strong>2 月按闰年规则</strong>：闰年 29 天，平年 28 天（能被 4 整除但不能被 100 整除，或能被 400 整除）</li></ul><p>因此 <code>20000229</code>（2000 年闰年）合法，而 <code>19000229</code>（1900 年平年）不合法。</p><h2 id="parse-返回的年龄是怎么计算的" tabindex="-1">parse() 返回的年龄是怎么计算的？ <a class="header-anchor" href="#parse-返回的年龄是怎么计算的" aria-label="Permalink to &quot;parse() 返回的年龄是怎么计算的？&quot;">​</a></h2><p>按周岁计算：当前年份减去出生年份，若今年生日尚未到则减 1。</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">parse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;622922197808118498&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).age; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 生日已过 → 当年周岁；生日未到 → 周岁 - 1</span></span></code></pre></div><p>注意年龄是<strong>调用时刻</strong>的动态值，不同日期调用可能返回不同结果。</p><h2 id="我的身份证号会被上传吗" tabindex="-1">我的身份证号会被上传吗？ <a class="header-anchor" href="#我的身份证号会被上传吗" aria-label="Permalink to &quot;我的身份证号会被上传吗？&quot;">​</a></h2><p><strong>不会。</strong> 本库无任何网络请求，所有计算（包括<a href="/china-id-card/playground.html">在线体验</a>页面）均在你的浏览器本地完成。库本身 0 依赖，你可以审查每一行<a href="https://github.com/tonyc726/china-id-card" target="_blank" rel="noreferrer">源码</a>。</p><h2 id="为什么在-typescript-里引入报类型错误" tabindex="-1">为什么在 TypeScript 里引入报类型错误？ <a class="header-anchor" href="#为什么在-typescript-里引入报类型错误" aria-label="Permalink to &quot;为什么在 TypeScript 里引入报类型错误？&quot;">​</a></h2><p>库自带类型声明（<code>dist/index.d.ts</code>），无需安装 <code>@types/*</code>。如遇问题，请确认：</p><ol><li><code>tsconfig.json</code> 中 <code>moduleResolution</code> 为 <code>bundler</code> 或 <code>node16</code>/<code>nodenext</code>（推荐）</li><li>使用 ES Module 引入方式：<code>import { isValid } from &#39;china-id-card&#39;</code></li></ol><h2 id="更多问题" tabindex="-1">更多问题 <a class="header-anchor" href="#更多问题" aria-label="Permalink to &quot;更多问题&quot;">​</a></h2><p>到 <a href="https://github.com/tonyc726/china-id-card/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 提问或反馈。</p>',32)])])}const g=e(o,[["render",d]]);export{k as __pageData,g as default};
